#include <print>

void swap_ptr(int* a, int* b) {
    int tmp = *a;
    *a = *b;
    *b = tmp;
}

int main() {
    double d = 1.5;
    double* p = &d;
    *p = 9.9;
    std::println("d = {}", d);
    std::println("*p 顺藤摸瓜 : {}", *p);

    int x = 1, y = 9;
    swap_ptr(&x, &y);
    std::println("换完：x = {}, y = {}", x, y);
    // 挨着类型写的 * 是户口，说 p 记的是 double 的门牌；表达式里的 * 是顺着地址取内容
    return 0;
}

